  );
  TestValidator.equals(
    "email matches registered email",
    customerProfile.email,
    customerEmail,
  );
  TestValidator.equals(
    "is_banned is false for new customer",
    customerProfile.is_banned,
    false,
  );
  TestValidator.equals(
