  TestValidator.predicate(
    "created_at is valid date-time format",
    () => !isNaN(new Date(session.created_at).getTime()),
  );
  TestValidator.predicate(
    "expired_at is valid date-time format",
    () => !isNaN(new Date(session.expired_at).getTime()),
  );
