  TestValidator.equals(
    "minQuantity filter count",
    minQuantityResponse.data.length,
    1,
  );
  TestValidator.equals(
    "minQuantity returns quantity 2 item",
    minQuantityResponse.data[0].quantity,
    2,
  );
  // 11. Filter by maxQuantity=1
