  // 14. Test data isolation - Customer A should not be able to list Customer B's cart items
  const crossAccess =
    await api.functional.ecommerceMall.customer.carts.items.index(
      customerAConnection,
      {
        cartId: cartB.id,
        body: {
          page: 1,
          limit: 20,
