    TestValidator.predicate(
      "item has variant_snapshot object",
      () => typeof firstItem.variant_snapshot === "object",
    );
    TestValidator.predicate(
      "item has seller_profile_snapshot object",
      () => typeof firstItem.seller_profile_snapshot === "object",
    );
