  const subcategory1 =
    await generate_random_ecommerce_mall_admin_categories_create(
      adminConnection,
      {
        body: {
          name: "Phones",
          description: "Mobile phones and accessories",
          parent_category_id: topLevelCategory.id,
        },
      },
    );
  typia.assert(subcategory1);
  const subcategory2 =
    await generate_random_ecommerce_mall_admin_categories_create(
      adminConnection,
      {
        body: {
          name: "Laptops",
          description: "Portable computers",
          parent_category_id: topLevelCategory.id,
        },
      },
    );
