    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: {
          sku_code: RandomGenerator.alphaNumeric(10),
          option_values: { size: "Small", color: "Blue" },
          stock_quantity: typia.random<
