        reviewId: initialReview.id,
        body: {
          rating: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
          text_content: "Good product but room for improvement",
        } satisfies IEcommerceMallReview.IUpdate,
      },
