  // 8. Test pagination with filtered results
  const paginatedFilter: IEcommerceMallCancellationRequest.IRequest = {
    status: "pending",
    page: 1,
    limit: 10,
  } satisfies IEcommerceMallCancellationRequest.IRequest;
