  const sortAscResponse =
    await api.functional.ecommerceMall.customer.refund_requests.status.index(
      customerTokenConnection,
      {
        body: {
          sortBy: "createdAt",
          sortOrder: "asc",
        } satisfies IEcommerceMallRefundRequest.IRequest,
      },
    );
  typia.assert(sortAscResponse);
