          option_values: {
            size: RandomGenerator.pick(["S", "M", "L", "XL"]),
            color: RandomGenerator.pick(["Red", "Blue", "Black", "White"]),
          },
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1>
