      createdAt: toISOStringSafe(input.created_at),
      updatedAt: toISOStringSafe(input.updated_at),
      itemCount,
      subtotal,
      tax,
      total,
      sellerSubtotals: sellerSubtotals.length > 0 ? sellerSubtotals : undefined,
      cartItems,
    };
  }
}

