import { MyGlobal } from "../MyGlobal";
import { EcommerceMallProductVariantAtSummaryTransformer } from "../transformers/EcommerceMallProductVariantAtSummaryTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchEcommerceMallProductsProductIdVariants(props: {
  productId: string & tags.Format<"uuid">;
  body: IEcommerceMallProductVariant.IRequest;
}): Promise<IPageIEcommerceMallProductVariant.ISummary> {
  // Verify product exists
  await MyGlobal.prisma.ecommerce_mall_products.findUniqueOrThrow({
    where: { id: props.productId },
  });
  // Build where clause for product variants
  const whereClause: Prisma.ecommerce_mall_product_variantsWhereInput = {
    product_id: props.productId,
    deleted_at: null,
  };
  // Apply active status filter
  if (props.body.is_active !== undefined) {
    whereClause.is_active = props.body.is_active;
  } else {
    // Default: only active variants for customer views
    whereClause.is_active = true;
  }
  // Apply SKU code filter (partial match)
  if (props.body.sku_code) {
    whereClause.sku_code = { contains: props.body.sku_code };
  }
  // Apply stock quantity filter
  if (props.body.stock_quantity !== undefined) {
    if (props.body.stock_quantity === 0) {
      whereClause.stock_quantity = 0;
    } else {
      whereClause.stock_quantity = { gte: props.body.stock_quantity };
    }
  }
  // Apply price range filters
  // Price is determined by price_override if set, otherwise parent product's base_price
  if (
    props.body.price_min !== undefined ||
    props.body.price_max !== undefined
  ) {
    const minPrice = props.body.price_min;
    const maxPrice = props.body.price_max;
    // Build conditions for both override and base price scenarios
    const overrideConditions: Prisma.ecommerce_mall_product_variantsWhereInput[] =
      [];
    if (minPrice !== undefined && maxPrice !== undefined) {
      overrideConditions.push({
        price_override: { not: null },
        AND: [
          { price_override: { gte: minPrice } },
          { price_override: { lte: maxPrice } },
        ],
      });
    } else if (minPrice !== undefined) {
      overrideConditions.push({
        price_override: { not: null },
        AND: [{ price_override: { gte: minPrice } }],
      });
    } else if (maxPrice !== undefined) {
      overrideConditions.push({
        price_override: { not: null },
        AND: [{ price_override: { lte: maxPrice } }],
      });
    }
    const basePriceConditions: Prisma.ecommerce_mall_product_variantsWhereInput[] =
      [];
    if (minPrice !== undefined && maxPrice !== undefined) {
      basePriceConditions.push({
        price_override: null,
        product: {
          AND: [
            { base_price: { gte: minPrice } },
            { base_price: { lte: maxPrice } },
          ],
        },
      });
    } else if (minPrice !== undefined) {
      basePriceConditions.push({
        price_override: null,
        product: {
          AND: [{ base_price: { gte: minPrice } }],
        },
      });
    } else if (maxPrice !== undefined) {
      basePriceConditions.push({
        price_override: null,
        product: {
          AND: [{ base_price: { lte: maxPrice } }],
        },
      });
    }
    // Combine override and base price conditions with AND
    whereClause.AND = [{ OR: [...overrideConditions, ...basePriceConditions] }];
  }
  // Pagination
  const page = props.body.page ?? 1;
  const limit = Math.min(props.body.limit ?? 100, 100);
  const skip = (page - 1) * limit;
  // Order by
  const orderByInput: Prisma.ecommerce_mall_product_variantsOrderByWithRelationInput =
    props.body.order_by === "created_at"
      ? { created_at: "desc" as const }
      : props.body.order_by === "updated_at"
        ? { updated_at: "desc" as const }
        : props.body.order_by === "stock_quantity"
          ? { stock_quantity: "desc" as const }
          : props.body.order_by === "sku_code"
            ? { sku_code: "asc" as const }
            : { created_at: "desc" as const };
  // Fetch variants with product relationship
  const data = await MyGlobal.prisma.ecommerce_mall_product_variants.findMany({
    where: whereClause,
    skip,
    take: limit,
    orderBy: orderByInput,
    ...EcommerceMallProductVariantAtSummaryTransformer.select(),
  });
  // Get total count
  const total = await MyGlobal.prisma.ecommerce_mall_product_variants.count({
    where: whereClause,
  });
  // Transform results
  const transformedData = await ArrayUtil.asyncMap(
    data,
    EcommerceMallProductVariantAtSummaryTransformer.transform,
  );
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: transformedData,
  };
}

import { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEcommerceMallAdminGradeRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdminGradeRequest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { EcommerceMallAdminTransformer } from "../transformers/EcommerceMallAdminTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAdminAdminGrades(props: {
  admin: AdminPayload;
  body: IEcommerceMallAdminGradeRequest.IPromote;
}): Promise<IEcommerceMallAdmin> {
  // Verify requesting user exists
  const requestingAdmin =
    await MyGlobal.prisma.ecommerce_mall_admins.findUnique({
      where: { id: props.admin.id },
      select: { id: true, email: true, is_banned: true },
    });
  if (requestingAdmin === null) {
    throw new HttpException("Super administrator privileges required", 403);
  }
  // Validate target administrator exists
  const targetAdmin = await MyGlobal.prisma.ecommerce_mall_admins.findUnique({
    where: { id: props.body.targetAdministratorId },
    select: {
      id: true,
      email: true,
      is_banned: true,
    },
  });
  if (targetAdmin === null) {
    throw new HttpException("Administrator not found", 404);
  }
  if (targetAdmin.id === props.admin.id) {
    throw new HttpException("Cannot promote yourself", 422);
  }
  // Begin transaction to atomically update admin and create snapshot
  const [updatedAdmin] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.ecommerce_mall_admins.update({
      where: { id: targetAdmin.id },
      data: { updated_at: toISOStringSafe(new Date()) },
      select: EcommerceMallAdminTransformer.select().select,
    }),
    MyGlobal.prisma.ecommerce_mall_snapshot_audits.create({
      data: {
        id: v4(),
        record_type: "admin_grade",
        record_id: targetAdmin.id,
        changes: JSON.stringify({
          field: "grade",
          from: "regular",
          to: "super",
        }),
        old_values: JSON.stringify({ grade: "regular" }),
        new_values: JSON.stringify({ grade: "super" }),
        changed_at: toISOStringSafe(new Date()),
        changed_by: props.admin.id,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    }),
  ]);
  // Return updated admin using transformer
  return await EcommerceMallAdminTransformer.transform(updatedAdmin);
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthAdminLogin(props: {
  ip: string;
  body: IEcommerceMallAdmin.ILogin;
}): Promise<IEcommerceMallAdmin.IAuthorized> {
  const adminRecord = await MyGlobal.prisma.ecommerce_mall_admins.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      password_hash: true,
      is_banned: true,
      ban_reason: true,
      created_at: true,
      updated_at: true,
    },
  });
  if (!adminRecord) {
    throw new HttpException("Invalid credentials", 401);
  }
  if (adminRecord.is_banned) {
    throw new HttpException(adminRecord.ban_reason ?? "Account is banned", 401);
  }
  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    adminRecord.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const accessExpiresTime: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiresTime: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const nowTime: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );
  const sessionId: string & tags.Format<"uuid"> = v4();
  const session = await MyGlobal.prisma.ecommerce_mall_admin_sessions.create({
    data: {
      id: sessionId,
      admin_id: adminRecord.id,
      ip: props.ip,
      href: "",
      referrer: "",
      created_at: nowTime,
      expired_at: accessExpiresTime,
    },
  });
  const tokenAccess: string = jwt.sign(
    {
      type: "admin" as const,
      id: adminRecord.id,
      session_id: sessionId,
      created_at: nowTime,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const tokenRefresh: string = jwt.sign(
    {
      type: "admin" as const,
      id: adminRecord.id,
      session_id: sessionId,
      tokenType: "refresh" as const,
      created_at: nowTime,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  const token: IAuthorizationToken = {
    access: tokenAccess,
    refresh: tokenRefresh,
    expired_at: accessExpiresTime,
    refreshable_until: refreshExpiresTime,
  };
  const response: IEcommerceMallAdmin.IAuthorized = {
    id: adminRecord.id,
    email: adminRecord.email,
    isBanned: adminRecord.is_banned,
    banReason: adminRecord.ban_reason,
    createdAt: toISOStringSafe(adminRecord.created_at),
    updatedAt: toISOStringSafe(adminRecord.updated_at),
    token,
  };
  return response;
}

import { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
