  } satisfies Prisma.ecommerce_mall_shipment_itemsWhereInput;
  // Parse sort parameter
  const orderByInput =
    ((): Prisma.ecommerce_mall_shipment_itemsOrderByWithRelationInput[] => {
      if (props.body.sort === "quantity") {
        return [
          {
            orderItem: {
              quantity: "asc",
            },
          },
