          item.shipment,
        ),
        orderItem: await EcommerceMallOrderItemAtSummaryTransformer.transform(
          item.orderItem,
        ),
      }) satisfies IEcommerceMallShipmentItem.ISummary,
  );
  return {
    data: transformedData,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

