import { postEcommerceMallAuthSellerRefresh } from "../../../../providers/postEcommerceMallAuthSellerRefresh";

@Controller("/ecommerceMall/auth/seller")
export class EcommercemallAuthSellerController {
  /**
   * Register a new seller account on the ecommerce mall platform. This operation creates an account that requires administrator approval before the seller can begin listing products and managing their shop.
   *
   * The registration process validates the provided email address against existing accounts in the ecommerce_mall_sellers table to ensure uniqueness. The password is hashed using industry-standard algorithms before being stored in the passwordHash field. Upon successful registration, the seller's approvalStatus is set to "pending" to indicate that administrator approval is required before selling privileges are granted.
   *
   * An email verification token is created in the ecommerce_mall_seller_email_verifications table to validate the seller's email address. This token can be used to verify email ownership before the account is fully activated. The seller can request password reset tokens via the ecommerce_mall_seller_password_resets table if needed in the future.
   *
   * The operation returns an IAuthorized response containing both access and refresh JWT tokens. The access token grants short-term authenticated access to seller-specific endpoints, while the refresh token enables token renewal without re-authentication. Session information is persisted in the ecommerce_mall_seller_sessions table for token management and concurrent session handling.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller registration information including email and password credentials
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Create seller account with email and password validation. Validate email uniqueness against ecommerce_mall_sellers.email, hash password and store in passwordHash field. Set approvalStatus to pending as new sellers require admin approval. Create email verification token in ecommerce_mall_seller_email_verifications table. Return IAuthorized response with JWT access token and refresh token stored in ecommerce_mall_seller_sessions. Password must meet minimum length requirements (12 characters), complexity (uppercase, lowercase, number, special character). Email must be valid RFC 5322 format. Store account creation timestamp in createdAt field.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallSeller.IJoin,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate a seller account using email and password credentials. This operation validates the seller's identity and grants authenticated access to seller-specific endpoints.
   *
   * The authentication process queries the ecommerce_mall_sellers table to find a record matching the provided email address. The password provided by the seller is hashed using the same algorithm used during registration and compared against the stored passwordHash field in the database. This ensures secure credential verification without exposing plaintext passwords.
   *
   * Before granting access, the operation verifies that the seller account has been approved by an administrator (approvalStatus equals "approved"). Accounts with pending approval status cannot authenticate until a super administrator reviews and approves the seller application. The operation also checks that the account is not banned (isBanned equals false) and not suspended (isSuspended equals false), as banned or suspended accounts have their selling privileges revoked.
   *
   * Upon successful authentication, the system generates JWT access and refresh tokens. The access token provides short-term authenticated access to seller endpoints, while the refresh token enables token renewal without requiring re-authentication. Both tokens are stored in the ecommerce_mall_seller_sessions table for session management and concurrent session handling. The seller can immediately use the access token to make authenticated API requests after receiving the IAuthorized response.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller login credentials including email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Authenticate seller with email and password credentials. Query ecommerce_mall_sellers table for matching email record. Verify passwordHash against provided password using same hashing algorithm. Check approvalStatus is "approved" to ensure admin approval was granted. Verify isBanned is false and isSuspended is false. On success, create JWT access token and refresh token. Store refresh token in ecommerce_mall_seller_sessions table. Return IAuthorized response with tokens. Handle login failures for invalid credentials, unapproved accounts, banned accounts, or suspended accounts.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallSeller.ILogin,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew the seller's access token using a valid refresh token without re-authenticating credentials. This operation enables continuous access to seller endpoints without requiring the seller to re-enter their email and password.
   *
   * The refresh operation validates the provided refresh token against records in the ecommerce_mall_seller_sessions table, confirming that the token exists, has not expired, and belongs to an active seller session. The operation also performs a sanity check on the seller account in ecommerce_mall_sellers, verifying that approvalStatus remains "approved" and that the account has not been banned or suspended since the token was issued.
   *
   * If all validations pass, the system generates a new access token with the standard expiration window and optionally a new refresh token if token rotation is enabled. The new tokens are stored in the ecommerce_mall_seller_sessions table, and any previous refresh token can be invalidated to prevent token reuse attacks. The operation returns an IAuthorized response containing the new tokens, allowing the seller to continue making authenticated API requests seamlessly.
   *
   * If the refresh token is expired, invalid, or the seller account has been banned or suspended, the operation fails and the seller must re-authenticate using the login operation. This ensures that compromised or stale tokens cannot be used indefinitely and that banned sellers cannot regain access through token renewal.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller refresh token for token renewal
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Refresh seller's access token using a valid refresh token. Query ecommerce_mall_seller_sessions table to validate refresh token exists and has not expired. Verify seller account is still approved (approvalStatus = approved) and not banned/suspended. Generate new access token and optional new refresh token. Store new refresh token in sessions table, invalidate old refresh token if rotation enabled. Return IAuthorized response with new tokens. Handle token expiration, invalid token, or revoked session scenarios.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceMallSeller.IRefresh,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

