import { postEcommerceMallAuthAdminRefresh } from "../../../../providers/postEcommerceMallAuthAdminRefresh";

@Controller("/ecommerceMall/auth/admin")
export class EcommercemallAuthAdminController {
  /**
   * Creates a new administrator account in the ecommerce mall system. This operation allows users to register as administrators by providing their email address and password credentials. The system validates that the email is unique and not already registered, and stores the password in hashed format for security.
   *
   * The registration process creates an admin record in the ecommerce_mall_admins table with the provided credentials. The admin account is initially created with isBanned set to false, indicating an active account status. Email verification is initiated by creating a verification token in the ecommerce_mall_admin_email_verifications table.
   *
   * Upon successful registration, the system generates JWT access and refresh tokens and stores the refresh token in the ecommerce_mall_admin_sessions table for session management. The returned authorized response contains these tokens along with the admin account information, enabling immediate authentication without requiring additional login.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator registration credentials including email and password
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Service layer creates new admin account by:
   * 1. Validating email format and uniqueness against ecommerce_mall_admins.email
   * 2. Validating password complexity requirements
   * 3. Hashing password using bcrypt
   * 4. Creating new record in ecommerce_mall_admins table with email, passwordHash, isBanned=false
   * 5. Generating JWT access token and refresh token
   * 6. Storing refresh token in ecommerce_mall_admin_sessions
   * 7. Creating email verification record in ecommerce_mall_admin_email_verifications
   * 8. Returning authorized response with tokens and admin info
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.IJoin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticates an existing administrator by validating their email and password credentials. This operation verifies the admin's identity by looking up their record in the ecommerce_mall_admins table and comparing the provided password against the stored passwordHash using secure bcrypt comparison.
   *
   * The authentication process checks that the admin account exists, is not banned, and the password credentials match. If any validation fails, the operation returns a 401 Unauthorized error. For banned accounts, the specific ban reason from the banReason field is included in the response.
   *
   * Upon successful authentication, the system generates new JWT access and refresh tokens. The refresh token is stored in the ecommerce_mall_admin_sessions table, which manages active sessions for admin authentication. The authorized response contains both tokens along with the admin account information, enabling the admin to access protected endpoints.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator login credentials including email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Service layer performs admin login by:
   * 1. Looking up admin record in ecommerce_mall_admins by email
   * 2. Verifying admin account exists and is not banned
   * 3. Validating password against stored passwordHash using bcrypt comparison
   * 4. Invalid credentials return 401 Unauthorized
   * 5. On success, generate JWT access token and refresh token
   * 6. Store refresh token in ecommerce_mall_admin_sessions (may update existing or create new)
   * 7. Return authorized response with tokens and admin info
   * 8. Handle concurrent session management if configured
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.ILogin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renews the administrator's JWT access token using a valid refresh token. This operation allows admins to obtain a new access token without re-authenticating their credentials, improving user experience while maintaining security.
   *
   * The refresh process validates the refresh token stored in ecommerce_mall_admin_sessions, checking that it has not expired and corresponds to an active admin account. If valid, the system generates a new JWT access token with fresh expiration time. The operation may also rotate the refresh token by invalidating the old token and creating a new session record, providing enhanced security against token reuse attacks.
   *
   * The authorized response contains the newly generated access and refresh tokens along with admin account information, enabling continued authenticated access to protected API endpoints without requiring password re-entry.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Current refresh token for renewal
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Service layer performs token refresh by:
   * 1. Extracting refresh token from request body
   * 2. Looking up refresh token in ecommerce_mall_admin_sessions
   * 3. Validating token is not expired and belongs to admin
   * 4. Generating new JWT access token with fresh expiration
   * 5. Optionally rotating refresh token (invalidate old, create new)
   * 6. Updating or creating new session record in ecommerce_mall_admin_sessions
   * 7. Return authorized response with new tokens and admin info
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceMallAdmin.IRefresh,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

