import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IEcommerceMallOrder } from "../../../../../../api/structures/IEcommerceMallOrder";
import { CustomerAuth } from "../../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../../decorators/payload/CustomerPayload";
import { getEcommerceMallCustomerOrdersOrderIdItemsStatusHistory } from "../../../../../../providers/getEcommerceMallCustomerOrdersOrderIdItemsStatusHistory";

@Controller("/ecommerceMall/customer/orders/:orderId/items/status-history")
export class EcommercemallCustomerOrdersItemsStatus_historyController {
  /**
   * Retrieve the complete status change history for all order items within a specified order.
   *
   * This operation provides customers and sellers with a chronological timeline of status transitions for each item in an order. It displays how order items progressed through the status workflow: paid → shipped → delivered → cancelled/refunded, with timestamps and audit information for each status change.
   *
   * The operation queries the ecommerce_mall_order_items table to retrieve all items belonging to the specified order, then aggregates the status change history from the ecommerce_mall_snapshot_audits table. Each item's response includes its current status, all previous status values in chronological order, and details about when each transition occurred.
   *
   * This endpoint is essential for order tracking, dispute resolution, and customer support. Customers use it to understand the delivery journey of their purchases, while sellers use it to monitor their order fulfillment progress and respond to cancellation or refund requests appropriately.
   *
   * @param connection
   * @param orderId The UUID of the order to retrieve status history for
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification 1. Validate that the orderId parameter is a valid UUID format
   * 2. Query ecommerce_mall_order_items table for all records where ecommerce_mall_order_id equals the provided orderId
   * 3. For each order item found, retrieve its status history from ecommerce_mall_snapshot_audits:
   *    - Filter snapshot records where record_type = 'order_item' and record_id equals the item's id
   *    - Order snapshots by changed_at ascending to show chronological progression
   *    - Extract old_values.status and new_values.status from each snapshot to build the status timeline
   * 4. For items with no status change history (first status recorded), include only the current status
   * 5. Join with ecommerce_mall_products and ecommerce_mall_product_variants to enrich item details with product name and variant options
   * 6. Filter out items marked as deleted (deleted_at IS NOT NULL) unless explicitly requested
   * 7. Return results sorted by item creation date (created_at) ascending
   * 8. Handle edge cases: order with no items, order not found, item with corrupted snapshot data
   * 9. Log all access attempts to ecommerce_mall_admin_audit_logs if requested by admin for audit purposes
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async statusHistory(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("orderId")
    orderId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallOrder.IItemStatusHistory> {
    try {
      return await getEcommerceMallCustomerOrdersOrderIdItemsStatusHistory({
        customer,
        orderId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

